#include <stdio.h>

int main() {
    char s[160];
    int count[4][14] = {0};

    scanf("%s", s);

    for (int i = 0; s[i] != '\0'; i += 3) {
        int value = (s[i] - '0') * 10 + (s[i + 1] - '0');
        char suit = s[i + 2];
        int idx;

        if (suit == 'C') idx = 0;
        else if (suit == 'E') idx = 1;
        else if (suit == 'U') idx = 2;
        else idx = 3;

        count[idx][value]++;
    }

    for (int i = 0; i < 4; i++) {
        int erro = 0;
        int missing = 0;

        for (int v = 1; v <= 13; v++) {
            if (count[i][v] > 1) {
                erro = 1;
                break;
            }
            if (count[i][v] == 0) {
                missing++;
            }
        }

        if (erro) {
            printf("erro\n");
        } else if (missing == 0) {
            printf("0\n");
        } else {
            printf("%d\n", missing);
        }
    }

    return 0;
}
